import{z as s,x as l,o as e,c as d,q as n,j as r,D as E,d as A,s as i,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"数据的频率选择","description":"","frontmatter":{"title":"数据的频率选择","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-frequency-choice.md","filePath":"quant/hfs-frequency-choice.md","lastUpdated":1791413859000}'),h={name:"quant/hfs-frequency-choice.md"};function c(p,a,u,f,D,m){const t=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="数据的频率选择" tabindex="-1">数据的频率选择 <a class="header-anchor" href="#数据的频率选择" aria-label="Permalink to &quot;数据的频率选择&quot;">​</a></h1><div class="epigraph"><p>频率不是「越多越好」的自由参数，是偏差-方差预算表上的一行：先写下噪声与信号的比，采样格才有着落。</p><footer>—— 据 Aït-Sahalia, Mykland and Zhang, Review of Financial Studies 2005 整理</footer></div><p><a href="/quant/hfs-highfreq-correlation">上一课</a>把多元流程收拢，还剩一个贯穿全课程的旋钮没有专课：采样频率。<a href="/quant/business-time-clock">交易时间对成交量时间</a>写过时钟的替换，<a href="/quant/obd-hf-vol-noise">高频波动率与微观噪声</a>在簿动力学语境写过噪声预算；本课把频率选择写成决策程序：稀疏格与全数据稳健估计是两条路线，选哪条由噪声-信号比与目标对象决定，不由习惯决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两条路线摆在桌面上。<strong>稀疏采样</strong>：五分钟格走天下，噪声未及污染、方差尚可——工程默认，但把大量观测丢掉。<strong>全数据稳健</strong>：tick 全进核或预平均，信息用满，代价是调参与对噪声结构的依赖。Aït-Sahalia、Mykland 与 Zhang（RFS 2005）把第一条路线做到底：给定噪声-信号比，存在使均方误差最小的采样间隔，间隔随噪声加重而变稀，其数值算例落在分钟量级。缺口是程序化：对一只具体标的、一个具体目标——方差、相关、跳还是 beta——频率怎么定、怎么验、什么时候换。</p><h3 id="决策程序" tabindex="-1">决策程序 <a class="header-anchor" href="#决策程序" aria-label="Permalink to &quot;决策程序&quot;">​</a></h3><p>第零步清洗：坏 tick 不进任何频率讨论。第一步测噪声：按上一单元的口径估 \\(\\sigma_\\varepsilon^2\\) 与噪声-信号比。第二步选路线：噪声-信号比小到高频端签名图接近平坦——全数据稳健估计，频率选择退化成带宽选择；比值大——要么定最优间隔的稀疏格，要么仍走稳健估计但接受更宽的带宽。第三步验平：选定频率附近的读数不应随格距系统性漂移。第四步子采样平均：多个错开格距的平均降方差，是稀疏路线的标配。第五步按时钟复核：日内波动的 U 形季节性使等间隔格在开盘尾盘过密、午盘过稀，成交量时钟或分时段处理是标准修正。</p><p><span class="marginnote">术语翻译：「噪声-信号比」= 微观结构噪声的方差 ÷ 真实波动的方差，好比「杂音音量 ÷ 音乐音量」。比值 1% 时几乎随便采；比值接近 1 时，采得越密画面越糊——这时「多采数据」反而是负资产。</span></p><p><span class="marginnote">错开子格的平均：\\(M\\) 个错开稀疏格平均把方差大约降到 \\(1/M\\)，偏差不变——这是稀疏路线的标配，也正是 TSRV 稀疏端的构造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按目标分开定频。<strong>方差</strong>：上面的程序全套适用，五分钟是量级参考不是定理。<strong>相关与 beta</strong>：密度不是瓶颈，对齐才是——先定对齐方案再谈格距，慢腿决定有效频率，<a href="/quant/hfs-highfreq-correlation">高频相关的估计</a>里刷新时间的信息税在这里变成频率的下限。<strong>跳的检测</strong>：分辨率越高定位越准，但噪声也越旺——先降噪再检验的次序不变，门限与窗口随格距重标。<strong>执行与簿观测</strong>：那是 \\(Y\\) 侧的问题，频率跟撮合事件走，与估计量的渐近无关。换标的、换制度（tick 调整、交易时段变化）时程序重跑，频率结论不迁移。</p>',11)),(e(),r(o,null,{default:E(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%B8%85%E6%B4%97%22%5D%20--%3E%20M%5B%22%E6%B5%8B%E5%99%AA%E5%A3%B0-%E4%BF%A1%E5%8F%B7%E6%AF%94%22%5D%0A%20%20M%20--%3E%20R%7B%22%E7%AD%BE%E5%90%8D%E5%9B%BE%E9%AB%98%E9%A2%91%E7%AB%AF%E5%B9%B3%E5%9D%A6%EF%BC%9F%22%7D%0A%20%20R%20--%3E%7C%22%E5%B9%B3%E5%9D%A6%22%7C%20A%5B%22%E5%85%A8%E6%95%B0%E6%8D%AE%E7%A8%B3%E5%81%A5%E4%BC%B0%E8%AE%A1%EF%BC%9A%E9%A2%91%E7%8E%87%E9%80%89%E6%8B%A9%E5%8F%98%E5%B8%A6%E5%AE%BD%E9%80%89%E6%8B%A9%22%5D%0A%20%20R%20--%3E%7C%22%E4%B8%8A%E7%BF%98%22%7C%20B%7B%22%E8%B7%AF%E7%BA%BF%22%7D%0A%20%20B%20--%3E%7C%22%E7%A8%80%E7%96%8F%22%7C%20S%5B%22%E5%AE%9A%E6%9C%80%E4%BC%98%E9%97%B4%E9%9A%94%20%2B%20%E9%94%99%E5%BC%80%E5%AD%90%E9%87%87%E6%A0%B7%E5%B9%B3%E5%9D%87%22%5D%0A%20%20B%20--%3E%7C%22%E7%A8%B3%E5%81%A5%22%7C%20A%0A%20%20A%20--%3E%20V%5B%22%E7%AD%BE%E5%90%8D%E5%9B%BE%E9%AA%8C%E5%B9%B3%20%2B%20%E6%97%B6%E9%92%9F%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20S%20--%3E%20V%0A%20%20V%20--%3E%20F%5B%22%E6%8C%89%E7%9B%AE%E6%A0%87%E5%AE%9A%E9%A2%91%EF%BC%9A%E6%96%B9%E5%B7%AE%E3%80%81%E7%9B%B8%E5%85%B3%E3%80%81%E8%B7%B3%E5%88%86%E5%88%AB%E6%88%90%E8%A1%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"偏差-方差的形状是程序的机制基础：采样越密，噪声偏差按噪声方差与格数增长；越稀，估计方差按观测数下降。两条曲线的和有最小值，最小值的位置由噪声-信号比决定——这是 AMZ 2005 的核心结果。子采样平均降方差的机制是把一个格距的随机性平均掉：错开的子格各自有偏，平均后方差下降而偏差不动，与 TSRV 的稀疏端同一构造。季节性以异方差的方式进来：等间隔格对 U 形波动的采样密度不均，等价于一天内非均匀加权，分时段或事件时钟能把这项拉直。",-1)),(e(),r(o,null,{default:E(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20DENSE%5B%22%E6%A0%BC%E8%B7%9D%E6%9E%81%E5%AF%86%22%5D%20--%3E%20NB%5B%22%E5%81%8F%E5%B7%AE%E4%B8%BB%E5%AF%BC%3A%20%E5%99%AA%E5%A3%B0%E9%A1%B9%E9%9A%8F%E6%A0%BC%E6%95%B0%E5%A2%9E%E9%95%BF%22%5D%0A%20%20SPARSE%5B%22%E6%A0%BC%E8%B7%9D%E6%9E%81%E7%A8%80%22%5D%20--%3E%20VB%5B%22%E6%96%B9%E5%B7%AE%E4%B8%BB%E5%AF%BC%3A%20%E8%A7%82%E6%B5%8B%E5%A4%AA%E5%B0%91%22%5D%0A%20%20NB%20--%3E%20SUM%5B%22MSE%20%3D%20%E5%81%8F%E5%B7%AE%20%2B%20%E6%96%B9%E5%B7%AE%22%5D%0A%20%20VB%20--%3E%20SUM%0A%20%20SUM%20--%3E%20MIN%5B%22%E5%86%85%E9%83%A8%E5%AD%98%E5%9C%A8%E6%9C%80%E4%BC%98%E6%A0%BC%E8%B7%9D%20%CE%94*%22%5D%0A%20%20NS%5B%22%E5%99%AA%E5%A3%B0-%E4%BF%A1%E5%8F%B7%E6%AF%94%E8%B6%8A%E9%AB%98%22%5D%20--%3E%20MOVE%5B%22%CE%94*%20%E8%B6%8A%E5%90%91%E7%A8%80%E7%AB%AF%E7%A7%BB%E5%8A%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比：给马拉松选手拍照测速——快门太快，拍到的是肌肉抖动（微观噪声）；快门太慢，只能凭起终点猜均速（方差大）。合适快门取决于「抖动比真实移动大多少倍」，这正是噪声-信号比在决定的事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>程序不产出普适频率：结论按标的、按日、按目标成立，迁移要重跑。稳健估计不消灭频率问题：带宽仍在、噪声结构仍在，只是把「选格距」换成「选带宽」，两者共享同一张预算表。事件时钟不是免费午餐：成交量时钟在量枯竭的时段会失速，隔夜与停牌另行处理。频率选择服务的是估计质量，不改变对象口径：含不含隔夜、中点还是成交价，这些决定先于任何格距。</p><p><span class="marginnote">常见误区：「五分钟格是行业黄金标准，所有标的照抄就行。」实际上五分钟只是经典算例落到的量级——流动性差的标的、最小报价单位调整之后的市场，最优格距可能差出好几倍。数字实例：同一程序在活跃股指与冷门小票上重跑，得到的 \\(\\Delta^\\ast\\) 可以一个在 1 分钟、一个在 15 分钟以上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两条路线：稀疏格（AMZ 2005 的最优间隔）与全数据稳健估计；选择由噪声-信号比与目标决定。</li><li>程序五步：清洗、测噪、选路、验平、子采样平均；时钟复核修正 U 形季节性。</li><li>按目标分频：方差看格距，相关看对齐，跳看降噪后的分辨率，执行跟事件走。</li><li>偏差-方差的最小值位置随噪声-信号比移动；「五分钟」是量级参考不是定理。</li><li>结论不迁移：换标的、换制度重跑程序。</li><li>出处：Aït-Sahalia, Mykland and Zhang, <em>How Often to Sample a Continuous-Time Process in the Presence of Market Microstructure Noise</em>, Review of Financial Studies, 2005。</li></ul>',6))])}const S=s(h,[["render",c]]);export{F as __pageData,S as default};
